function logo(): string
{
    return '<span class="brand-mark"><svg viewBox="0 0 48 48"><path d="M24 3 43 14v20L24 45 5 34V14L24 3Z"/><path d="m13 17 11 6 11-6M13 31l11-6 11 6M24 23v22"/></svg></span><span class="brand-copy"><strong>КРЫМСКИЙ</strong><em>МЕДОСБОР</em></span>';
}

function pageUrl(string $page, array $extra = []): string
{
    return '/?'.http_build_query(['page' => $page] + $extra);
}

function headerHtml(string $active): string
{
    $items = ['home' => 'Главная', 'products' => 'Товары', 'blog' => 'Блог', 'gallery' => 'Галерея', 'certificates' => 'Сертификаты', 'contacts' => 'Контакты'];
    $links = '';
    foreach ($items as $key => $label) {
        $href = $key === 'home' ? '/' : pageUrl($key);
        $links .= '<a class="'.($active === $key ? 'is-active' : '').'" href="'.$href.'">'.$label.'</a>';
    }

    return '<header class="site-header"><div class="container nav-wrap"><a class="brand" href="/">'.logo().'</a><button class="menu-toggle" type="button" data-menu-toggle aria-label="Открыть меню"><span></span><span></span></button><nav class="main-nav" data-menu>'.$links.'</nav><div class="nav-actions"><div class="lang-switcher"><a class="active">RU</a><span>/</span><a>EN</a></div><a class="circle-link" href="'.pageUrl('contacts').'" aria-label="Заказать"><span>↗</span></a></div></div></header>';
}

